from sqlib import *
import sympy as sp, math
x,y,k,p,t=sp.symbols('x y k p t'); R=sp.Rational; s2,s3,s5=sp.sqrt(2),sp.sqrt(3),sp.sqrt(5); cl=math.isclose
def S(e,v=x,dom=sp.S.Reals): return sorted([sp.nsimplify(sp.simplify(q)) for q in sp.solveset(e,v,dom)],key=float)
def SS(a,b): return sorted([(r[x],r[y]) for r in sp.solve([a,b],[x,y],dict=True) if all(v.is_real for v in r.values())],key=lambda q:(float(q[0]),float(q[1])))
def ineq(e): return sp.solve_univariate_inequality(e,x,relational=False)
