E57[19]=("একটি ধনাত্মক ভগ্নাংশের হর লব অপেক্ষা 3 বেশি এবং ভগ্নাংশ ও তার বিপরীত ভগ্নাংশের যোগফল 29/10। ভগ্নাংশটি নির্ণয় কর।","x/(x + 3) + (x + 3)/x = 29/10 ⇒ 10{x² + (x + 3)²} = 29x(x + 3) ⇒ 9x² + 27x − 90 = 0 ⇒ x² + 3x − 10 = 0\nx = 2 (ধনাত্মক) ⇒ ভগ্নাংশ 2/5 (যাচাই: 2/5 + 5/2 = 29/10 ✓)",'ক')
assert S(x/(x+3)+(x+3)/x-R(29,10))==[-5,2]
